1	// Model access for the agent. The pipeline only talks to LlmClient; the real
2	// adapter lives in openai-llm.ts (built by gateway-client.ts) and tests use
3	// fake-llm.ts. Like providers, clients return errors instead of throwing.
4	
5	import type { LlmCost, LlmKeySpend, LlmTokenUsage } from "./llm-cost";
6	
7	export interface LlmMessage {
8	  readonly role: "system" | "user";
9	  readonly content: string;
10	}
11	
12	export interface LlmRequest {
13	  // Always RunConfig.model; never hardcoded by a client.
14	  readonly model: string;
15	  readonly messages: readonly LlmMessage[];
16	  // Always RunConfig.max_output_tokens_per_call.
17	  readonly max_output_tokens: number;
18	  // Always LLM_TEMPERATURE (0).
19	  readonly temperature: number;
20	}
21	
22	// Why a model call failed.
23	export type LlmErrorCategory =
24	  | "rate_limited" // 429, after any allowed retries
25	  | "timeout" // an attempt timed out, or the call ran out of time
26	  | "auth_failed" // 401 / 403
27	  | "provider_unavailable" // 5xx or no connection
28	  | "malformed_response" // a 2xx response without a usable completion
29	  | "model_error"; // anything else, e.g. 400 / 404 / 422
30	
31	// Where the response headers were read from: withResponse() on an unwrapped
32	// SDK promise, the fetch hook (needed once wrapOpenAI has wrapped the
33	// client), the SDK error of a failed request, or nowhere.
34	export type LlmHeaderSource = "with_response" | "fetch_hook" | "error_response" | "none";
35	
36	// Facts about one logical model call, success or failure. Secrets never
37	// appear here.
38	export interface LlmCallMeta {
39	  readonly model: string;
40	  // HTTP requests made for this logical call: 1 plus retries.
41	  readonly attempts: number;
42	  // Milliseconds waited before each retry.
43	  readonly retry_waits_ms: readonly number[];
44	  // Absent when the response did not report both token counts.
45	  readonly usage?: LlmTokenUsage;
46	  readonly cost: LlmCost;
47	  readonly key_spend?: LlmKeySpend;
48	  readonly header_source: LlmHeaderSource;
49	}
50	
51	export interface LlmError {
52	  readonly category: LlmErrorCategory;
53	  // Redacted: never contains an API key or Authorization header.
54	  readonly message: string;
55	  readonly status?: number;
56	}
57	
58	export type LlmResponse =
59	  | {
60	      readonly ok: true;
61	      readonly text: string;
62	      // True when the model stopped because it hit max_output_tokens.
63	      readonly truncated: boolean;
64	      readonly meta: LlmCallMeta;
65	    }
66	  | { readonly ok: false; readonly error: LlmError; readonly meta: LlmCallMeta };
67	
68	export interface LlmClient {
69	  // True when the client records its own LLM spans (e.g. via wrapOpenAI), so
70	  // the pipeline must not record the prompt and completion a second time.
71	  readonly records_llm_spans: boolean;
72	  complete(request: LlmRequest): Promise<LlmResponse>;
73	}
