82	function buildLlm(kind: Args["llm"]): LlmClient {
83	  if (kind === "fake") return new FakeLlmClient();
84	  const apiKey = process.env.LITELLM_API_KEY;
85	  if (apiKey === undefined || apiKey.trim() === "") {
86	    throw new UsageError("LITELLM_API_KEY is not set; it is required for --llm real.");
87	  }
88	  return createGatewayLlmClient({ apiKey });
89	}
90	
91	// Fake-client token counts are made up; only real gateway usage is measured.
92	function tokenBasis(kind: Args["llm"]): "simulated" | "measured" {
93	  return kind === "fake" ? "simulated" : "measured";
94	}
95	
96	function fileSafe(label: string): string {
97	  return label.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "run";
98	}
99	
100	// Delegates to the real or fake client and records only the hashes of the
101	// system messages it is asked to send, never their text.
102	class HashingLlmClient implements LlmClient {
103	  readonly system_hashes = new Set<string>();
104	
105	  constructor(private readonly inner: LlmClient) {}
106	
107	  get records_llm_spans(): boolean {
108	    return this.inner.records_llm_spans;
109	  }
110	
111	  complete(request: LlmRequest): Promise<LlmResponse> {
112	    recordSystemHashes(request.messages, this.system_hashes);
113	    return this.inner.complete(request);
114	  }
115	}
