147	function buildReport(
148	  args: Args,
149	  config: RunConfig,
150	  icp_description: string,
151	  result: PipelineResult,
152	  started_at: string,
153	  prompt: { readonly system_prompt_hashes: readonly string[] },
154	  validation: PostHocValidation,
155	  final_validation: FinalValidation,
156	  spend: ProviderSpend,
157	) {
158	  const { run, usage } = result;
159	  const fact_provider = args.provider;
160	  const simulated = args.provider === "fixture";
161	  return {
162	    started_at,
163	    label: args.label,
164	    pipeline: args.pipeline,
165	    provider: args.provider,
166	    fact_provider,
167	    tracing: args.tracing ? "on" : "off",
168	    search_sort: simulated ? null : CRUSTDATA_SEARCH_SORT,
169	    icp_description,
170	    // ICP parameters from the flags; no company data.
171	    icp_flags: simulated ? null : { industry: args.industry, country: args.country, sizes: args.sizes },
172	    config_name: args.config,
173	    config,
174	    trace_id: run.trace_id,
175	    status: result.status,
176	    counts: run.counts,
177	    cost_usd_by_step: run.cost_usd_by_step,
178	    timings_ms_by_step: run.timings_ms_by_step,
179	    cost_basis: {
180	      provider: simulated ? "simulated" : "measured",
181	      ...(simulated && { provider_cost_per_record_usd: SIMULATED_COST_PER_RECORD }),
182	      provider_cost_usd: { search: spend.search, enrich: spend.enrich, total: spend.search + spend.enrich },
183	      llm_calls_by_basis: usage.llm_cost.calls_by_basis,
184	    },
185	    provider_usage: usage.provider,
186	    llm: {
187	      mode: args.llm,
188	      token_basis: tokenBasis(args.llm),
189	      calls: usage.llm_calls,
190	      http_attempts: usage.llm_http_attempts,
191	      input_tokens: run.counts.llm_input_tokens,
192	      output_tokens: run.counts.llm_output_tokens,
193	      gateway_reported_usd: usage.llm_cost.gateway_reported_usd,
194	      estimated_usd: usage.llm_cost.estimated_usd,
195	      known_usd: usage.llm_cost.known_usd,
196	      cost_complete: usage.llm_cost.complete,
197	    },
198	    prompt_provenance: {
199	      prompt_version: PROMPT_VERSION,
200	      prompt_safety_rules_sha256: sha256Hex(PROMPT_SAFETY_RULES),
201	      system_prompt_hashes: prompt.system_prompt_hashes,
202	    },
203	    post_hoc_validation: validation,
204	    // Both pipelines: the delivered (post-enrichment) records, validated in
205	    // memory. Codes, field names, counts and company ids only.
206	    final_record_validation: final_validation,
207	    // Both pipelines: the final outreach drafts, measured after the fact with
208	    // the same function (for improved, the drafts that survived the guards).
209	    outreach_kept: summarizeOutreachKept(result.prospects),
210	    citation_metrics: computeBaselineCitationMetrics(result, fact_provider),
211	    // Improved only: its own guardrail counts (null when it stopped before
212	    // validation) and findings by code. Counts and ids only.
213	    improved_metrics: args.pipeline === "improved" ? (result.metrics ?? null) : null,
214	    guard_findings: args.pipeline === "improved" ? summarizeGuardFindings(result.prospects, result.metrics) : null,
215	    issue_codes: result.issues.map((i) => i.code),
216	    company_ids: result.prospects.map((p) => p.raw.crustdata_company_id),
217	    prospects: result.prospects.map((p) => ({
218	      company_id: p.raw.crustdata_company_id,
219	      enrichment: p.enrichment.status,
220	      assessment: p.assessment.status,
221	      llm_call_number: p.llm_call?.call_number ?? null,
222	    })),
223	  };
224	}
