226	function buildProvider(args: Args, config: RunConfig): CompanyProvider & { readonly budget: BudgetGuard } {
227	  if (args.provider === "fixture") {
228	    return new FixtureProvider({ config, cost_per_record: SIMULATED_COST_PER_RECORD });
229	  }
230	  // Presence was checked by validateRunArgs before anything was built.
231	  return new CrustdataProvider({
232	    api_key: process.env.CRUSTDATA_API_KEY ?? "",
233	    budget: new BudgetGuard(config),
234	    search_sort: CRUSTDATA_SEARCH_SORT,
235	  });
236	}
