238	// Tracing is loaded lazily so a crustdata or --trace off run never imports or
239	// initialises neatlogs.
240	async function withTracing<T>(
241	  args: Args,
242	  fn: (tracer: PipelineTracer) => Promise<T>,
243	): Promise<T> {
244	  if (!args.tracing) return fn(noopTracer);
245	  const { span } = await import("neatlogs");
246	  const { neatlogsTracer } = await import("../src/core/agent/neatlogs-tracer");
247	  const { closeTracing, initTracing } = await import("../src/core/observability/tracing");
248	  await initTracing({ run_label: args.label });
249	  try {
250	    return await span({ kind: "WORKFLOW", name: "signalscout_run" }, () => fn(neatlogsTracer))();
251	  } finally {
252	    await closeTracing();
253	  }
254	}
