339	      ` ids=${finalVal.changed_by_enrichment.company_ids.join(",") || "none"}`,
340	  );
341	  const m = computeBaselineCitationMetrics(result, args.provider);
342	  if (args.pipeline === "baseline") {
343	    console.log(
344	      `citations assessed=${m.assessed} drafts=${m.outreach_drafts} cited=${m.cited_fact_ids} citeable=${m.citeable} missing=${m.missing}` +
345	        ` cross_company=${m.cross_company} model_provider=${m.model_provider} uncertain=${m.uncertain}` +
346	        ` other_non_citeable=${m.other_non_citeable} drafts_with_violations=${m.drafts_with_violations.count}`,
347	    );
348	  } else if (result.metrics) {
349	    const im = result.metrics;
350	    console.log(
351	      `improved rejected=${im.rejected.count} flagged=${im.flagged.count} duplicates_removed=${im.duplicates_removed.count}` +
352	        ` eligible=${im.enrichment.eligible.count} requested=${im.enrichment.requested.count} enriched=${im.enrichment.enriched.count}` +
353	        ` assessments_failed=${im.assessments_failed.count} outreach_suppressed=${im.outreach_suppressed.count}` +
354	        ` claim_violations=${im.claim_violations.count} (drafts=${im.claim_violations.drafts})`,
355	    );
356	    const g = summarizeGuardFindings(result.prospects, im);
357	    const byCode = (r: Readonly<Record<string, number>>) =>
358	      Object.entries(r)
359	        .map(([code, n]) => `${code}=${n}`)
360	        .join(",") || "none";
361	    console.log(`guards   findings: ${byCode(g.findings_by_code)}  claim_violations: ${byCode(g.claim_violations_by_code)}`);
362	  } else {
363	    console.log("improved metrics unavailable (the run stopped before validation)");
364	  }
365	  console.log(formatOutreachLine(summarizeOutreachKept(result.prospects), m));
366	  console.log(`issues   ${result.issues.map((i) => i.code).join(", ") || "none"}`);
367	  console.log(`report   ${path}`);
368	  if (result.status === "stopped") {
369	    console.error("The run stopped early; see the issue codes above.");
370	  }
371	  process.exitCode = exitCodeForStatus(result.status);
372	}
373	
374	main().catch((err) => {
375	  console.error(
376	    err instanceof UsageError ? err.message : `Run failed: ${err instanceof Error ? err.message : "unknown error"}`,
377	  );
378	  process.exitCode = exitCodeForError(err);
379	});
