89	const ISSUE_NOTICES: Readonly<Record<string, string | undefined>> = {
90	  enrich_partial: "Some companies could not be enriched, so those use basic search data only.",
91	  enrich_no_results: "No companies could be enriched, so results use basic search data only.",
92	  enrich_failed: "Enrichment failed, so results use basic search data only.",
93	  enrich_budget_exhausted: "The enrichment budget was reached before every company was enriched.",
