113	  missing_domain: "The company has no primary domain.",
114	  junk_website: "The website is not a company site.",
115	  duplicate_domain: "The company duplicates another result.",
116	  size_headcount_mismatch: "The size range and headcount disagree.",
117	  missing_linkedin: "The company has no LinkedIn page.",
118	};
