120	const GENERIC_FINDING_MESSAGE = "The assessment failed a check.";
121	const FINDING_MESSAGES: Readonly<Record<string, string | undefined>> = {
122	  fit_score_out_of_range: "The fit score is outside 0-100.",
123	  criterion_score_out_of_range: "A criterion score is outside 0-100.",
124	  missing_criterion: "A requested criterion was not scored.",
125	  unexpected_criterion: "A criterion was scored that was not requested.",
126	  duplicate_criterion: "A criterion was scored more than once.",
127	  unknown_fact_reference: "A score references an unknown fact.",
128	  uncertain_fact_reference: "A score references an uncertain fact.",
129	  no_citations: "The outreach cites no facts.",
