137	function scrubValidation(v: Validation | undefined): Validation | undefined {
138	  if (v === undefined) return v;
139	  return {
140	    ...v,
141	    issues: v.issues.map((i) => ({ ...i, reason: VALIDATION_REASONS[i.code] ?? GENERIC_VALIDATION_REASON })),
142	  };
143	}
