156	// Returns a copy of the pipeline result in which every free-text field that
157	// can carry upstream, model-error or user text is replaced by a fixed string
158	// chosen by its code or reason. Never mutates its input. Company data, facts
159	// and model assessments are the payload and pass through unchanged.
160	export function scrubResult(result: PipelineResult): PipelineResult {
161	  return {
162	    ...result,
163	    run: { ...result.run, input_description: "Run criteria withheld." },
164	    issues: result.issues.map((i) => ({ ...i, message: ISSUE_NOTICES[i.code] ?? GENERIC_ISSUE_MESSAGE })),
165	    prospects: result.prospects.map((p) => {
166	      const assessment =
167	        p.assessment.status === "failed"
168	          ? {
169	              ...p.assessment,
170	              message: FAILED_ASSESSMENT_MESSAGES[p.assessment.reason] ?? GENERIC_ASSESSMENT_MESSAGE,
171	            }
172	          : p.assessment;
173	      const scrubbed = { ...p, assessment };
174	      const search_validation = scrubValidation(p.search_validation);
175	      const validation = scrubValidation(p.validation);
176	      return {
177	        ...scrubbed,
178	        ...(search_validation !== undefined ? { search_validation } : {}),
179	        ...(validation !== undefined ? { validation } : {}),
180	        ...(p.checks !== undefined
181	          ? {
182	              checks: {
183	                ...p.checks,
184	                assessment: scrubCheck(p.checks.assessment),
185	                ...(p.checks.claims !== undefined ? { claims: scrubCheck(p.checks.claims) } : {}),
186	              },
187	            }
188	          : {}),
189	      };
190	    }),
191	  };
192	}
193	
194	function respond(httpStatus: LiveOutcome["httpStatus"], body: LiveBody): LiveOutcome {
195	  return { httpStatus, body };
196	}
197	
198	const simple = (
199	  httpStatus: LiveOutcome["httpStatus"],
200	  status:
201	    | "live_disabled"
202	    | "invalid_code"
203	    | "no_runs_left"
204	    | "run_in_progress"
205	    | "budget_exhausted"
206	    | "run_failed"
207	    | "live_unavailable",
208	): LiveOutcome => respond(httpStatus, { status, message: MESSAGES[status] });
209	
210	// For callers that fail before runLive (e.g. configuration is missing).
211	export const liveUnavailable = (): LiveOutcome => simple(503, "live_unavailable");
212	
213	function rateLimited(retryAfterSeconds: number): LiveOutcome {
214	  const seconds = Number.isFinite(retryAfterSeconds) ? Math.max(1, Math.ceil(retryAfterSeconds)) : 60;
215	  return respond(429, { status: "rate_limited", retryAfterSeconds: seconds, message: MESSAGES.rate_limited });
216	}
217	
218	function noticesFromIssues(issues: readonly { readonly code: string }[]): string[] {
219	  const out: string[] = [];
220	  for (const issue of issues) {
221	    const text = ISSUE_NOTICES[issue.code];
222	    if (text !== undefined && !out.includes(text)) out.push(text);
223	  }
224	  return out;
225	}
