235	  readonly store: LiveStore;
236	  readonly hmacSecret: string;
237	  // null when live keys are not configured: synthetic codes still run.
238	  readonly live: LiveKeys | null;
239	  readonly now: () => Date;
240	  // Live factories. Never called in synthetic mode.
241	  readonly createProvider: (keys: LiveKeys, config: RunConfig) => LiveProviderBundle | Promise<LiveProviderBundle>;
242	  readonly createLlm: (keys: LiveKeys) => LlmClient | Promise<LlmClient>;
243	  readonly synthetic?: SyntheticDependencies;
244	  // Builds the 200 body's results for both modes.
245	  readonly toResults: ToResults;
